import { ListItem, ModuleItem } from "@/components/CustomPage/interface";
import { PageItem } from "@/types/page";
import ajax from "@/utils/ajax";
import app from "@/store/app";
import _ from 'lodash';
import { DesignListItem } from "@/types/design";
import { moduleStore } from "react-converter-code";
import { getModuleItem } from "@/utils/module";
import { getBuilderItems } from "src/utils/builder";
import { CustomPageStore } from "@/components/CustomPage";


class Store {

    pages: Record<string, CustomPageStore> = {};
    pageNode: Record<string, DesignListItem[]> = {};
    pageList: PageItem[] = [];
    moduleList: ModuleItem[] = [];
    listNode: Record<string, DesignListItem> = {};
    
    getList = async () => {
        const res = await ajax.post('/apijson/get', {
            "Module[]": {
                Module: {
                    // "@column": "id,moduleId,name,imgUrl,nickname,description,deletedTime,category,display,content,extraInfo,jsxRender,platform,price,manufacturer,props,source" 
                }
            },
            "Page[]": {
                Page: {
                }
            }
        })

        const { Module, Page } = res;

        this.pageList = Page.map((o) => {
            return {
                ...o,
                extraInfo: o.extraInfo? JSON.parse(o.extraInfo) :  {},
                content: o.content? JSON.parse(o.content) : {},
            }
        })
        
        this.moduleList = Module.map((o) => {
            const item = getModuleItem(o);
            moduleStore.addElement(item);
            return {
                id: o.id,
                ...item,
            }
        })
    }


    // 加载所有模块list
    initList = async () => {
        for (const item of this.pageList) {
            const store = new CustomPageStore({ uid: item.id, name: item.title });
            await store.setData(item.content);
            this.pages[item.id] = store;
            const list = store.getDataAllList();
            _.assign(
                this.listNode,
                list.reduce((objs, o) => {
                    return { 
                        ...objs, [o.id]: {
                            ...o,
                            // parentIds: [],
                            pageId: item.id,
                            builders: getBuilderItems(o.props, o.key),
                        } as DesignListItem
                    }
                }, {}) 
            )
        }

        for (const item of this.moduleList) {
            const store = new CustomPageStore({ uid: item.moduleId, name: item.name, isComponent: true });
            await store.setData(item.content);
            this.pages[item.moduleId] = store;
            _.assign(this.listNode, store.getDataAllList().reduce((objs, o) => ({ 
                ...objs, [o.id]: {
                    ...o,
                    // parentIds: [],
                    moduleId: item.moduleId,
                    builders: getBuilderItems(o.props, o.key),
                } as DesignListItem
            }), {}) )
        }


        // 记录自定义组件数据
        const keys = Object.keys(this.listNode);
        for (const key of keys) {
            const item = this.listNode[key];
            if(this.pages[item.key]){
                if(!this.pageNode[item.key]) this.pageNode[item.key] = [];
                this.pageNode[item.key].push(item);
            }
        }
    }



    /**
     * 初始化编辑器
     */
    init = async () => {
        this.listNode = {};
        await this.getList();
        await this.initList();
        console.log('init',this.pageList, this.moduleList, this.listNode);
    }
}

export default new Store;